import { usageOf } from "../store/usage";

export function limitFor(orgId: string): number {
  return orgId.startsWith("trial-") ? 100 : 1000;
}

export function allowRequest(id: string): boolean {
  if (usageOf(id) >= limitFor(id)) return false;
  return true;
}

